def max_depth(s: str) -> int:
    """ Helper function to calculate the maximum depth of a string of parentheses."""
    max_depth = 0
    current_depth = 0
    for c in s:
        if c == '(':
            current_depth += 1
            max_depth = max(max_depth, current_depth)
        elif c == ')':
            current_depth -= 1
    return max_depth

